/// <summary>
/// COC extension for CustRecurrenceInvoiceGenerationService to support MET toggle that forces system date for invoice and generation dates and disable date controls in dialog.
/// </summary>
[ExtensionOf(classStr(CustRecurrenceInvoiceGenerationService))]
internal final class METCustRecurrenceInvoiceGenerationService_Extension
{
    private boolean validationCheckWithUseofSystemDate;

}

Method.Source:
/// <summary>
///    Adds the query build range for the <c>CustRecurrenceInvoice</c> query object.
/// </summary>
/// <param name="_query">
///    An instance of the <c>CustRecurrenceInvoice</c> query object.
/// </param>
/// <param name="_custInvoiceTemplateName">
///    The name of a customer recurrence invoice template.
/// </param>
/// <returns>
///    The updated <c>CustRecurrenceInvoice</c> query object.
/// </returns>
protected QueryBuildRange queryBuildUpdate(Query _query, str _custInvoiceTemplateName)
{
    // NOTE: 1. If 'Generate recurrence invoice' process execution is set as Batch job with scheduled recurrence(as part of std framework), then customization is to set the Invoice date and Generation date to system date
    //       2. Then validation check is performed with system date and result is stored in class variable, which is used in next method to stop the process if validation fails. This is done as the scheduled recurrence batch execution does not
    //          perform or trigger the validation at occurs(CustRecurrenceInvoiceDataContract/validate) while submitting it as batch job.
    //       3. generateInvoices call set the StopProcess variable to False again std call. Therefore validating in call for generateInvoices, capturing the value of validation in global variable and setting it here to stop the process if validation fails when toggle is enabled.
    //       4. this method does not have the contract class as paramter to directly call the validation from contract class.

    if (!stopProcess) // To avoid overwriting the value of stopProcess variable if validation failed in std call.
    {
        stopProcess =  validationCheckWithUseofSystemDate;
    }

    return next queryBuildUpdate(_query, _custInvoiceTemplateName);
}

/// <summary>
///    Generates the recurrence invoices based on the <c>CustRecurrenceInvoiceDataContract</c> class.
/// </summary>
/// <param name="_custRecurrenceInvoiceDataContract">
///    An instance of <c>CustRecurrenceInvoiceDataContract</c> class.
/// </param>
/// <exception cref="M:Exception::UpdateConflictNotRecovered">
///    An unrecoverable update conflict occurred.
/// </exception>
/// <exception cref="M:Exception::UpdateConflict">
///    An update conflict occurred.
/// </exception>
public void generateInvoices(CustRecurrenceInvoiceDataContract _custRecurrenceInvoiceDataContract)
{
    if (_custRecurrenceInvoiceDataContract.parmUseSystemDateForRecurrence())
    {
        TransDate systemDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        _custRecurrenceInvoiceDataContract.parmRecurrenceInvoiceDate(systemDate);
        _custRecurrenceInvoiceDataContract.parmRecurrenceGenerationDate(systemDate);

        validationCheckWithUseofSystemDate = _custRecurrenceInvoiceDataContract.validate();
    }

    next generateInvoices(_custRecurrenceInvoiceDataContract);
}
